/// <summary>
/// يقرأ ملف CSV لتاريخ انتقال المهام بين الأعمدة، ويحسب:
/// throughput · cycle time (متوسط/وسيط/p85) · WIP الحالي.
/// يساعد على إثبات الاختناق بالأرقام بدل الحدس في الـretro.
/// </summary>
public static class FlowMetrics
{
    public sealed record Transition(string TaskId, string Column, DateTimeOffset At);

    public static void Report(IEnumerable<Transition> transitions)
    {
        var byTask = transitions
            .GroupBy(t => t.TaskId)
            .ToDictionary(g => g.Key, g => g.OrderBy(t => t.At).ToList());

        var cycleTimes = new List<double>();
        foreach (var (_, steps) in byTask)
        {
            var started = steps.FirstOrDefault(s => s.Column == "in-progress");
            var done = steps.FirstOrDefault(s => s.Column == "done");
            if (started is null || done is null) continue;
            cycleTimes.Add((done.At - started.At).TotalDays);
        }

        if (cycleTimes.Count == 0) { Console.WriteLine("لا توجد مهام مكتملة"); return; }

        cycleTimes.Sort();
        var p85 = cycleTimes[(int)Math.Floor((cycleTimes.Count - 1) * 0.85)];
        var wip = byTask.Count(kv =>
            kv.Value.Any(s => s.Column == "in-progress" || s.Column == "review" || s.Column == "testing")
            && !kv.Value.Any(s => s.Column == "done"));

        Console.WriteLine($"المهام المكتملة: {cycleTimes.Count}");
        Console.WriteLine($"متوسط Cycle time: {cycleTimes.Average():F1} يوم");
        Console.WriteLine($"وسيط: {cycleTimes[cycleTimes.Count / 2]:F1} يوم");
        Console.WriteLine($"p85 (توقع واقعي): {p85:F1} يوم");
        Console.WriteLine($"WIP الحالي: {wip}");
        Console.WriteLine($"التوقع (ليتل): {wip / Math.Max(1, cycleTimes.Count / 7.0):F1} أسبوع للتسليم");
    }
}

/*
 لماذا p85 لا المتوسط؟
   المتوسط يخفي الحالات الشاذة (مهمة عالقة شهرًا). p85 يقول: 85% من المهام
   تُسلَّم في هذا الزمن أو أقل — وهو ما تبنى عليه الوعود للعميل.
